/* Realtek RTL8822BU (0bda:b812 and kin), a 2x2 802.11ac USB card: the chip, as the
 * driver's files share it.
 *
 * A port of Linux's rtw88 (drivers/net/wireless/realtek/rtw88): the same register
 * sequences in the same order, checked write by write against a
 * usbmon recording of rtw88 bringing this card up (tests/rtwtrace.py). Function
 * names say which rtw88 function each follows. The register names are rtw88's own
 * (rtw_reg.h) and the tables its own (rtw8822b_table.c), both generated by
 * tools/rtw88_import.py.
 *
 * Unlike the AIC8800 this is a SoftMAC chip: its firmware keeps rates and power,
 * nothing more. Scanning, joining and the data path's 802.11 framing are the
 * host's (src/wireless/softmac/).
 *
 * The bring-up so far: registers, the efuse (the card's own address), power on
 * and the firmware.
 */

#ifndef XE_RTW_H
#define XE_RTW_H

#include "kernel.h"
#include "usb.h"
#include "net.h"
#include "rtw_reg.h"
#include "rtw8822b_table.h"
#include "softmac.h"

#define RTW_VENDOR          0x0BDAu
#define RTW_FW_FILE         "rtw8822b_fw.bin"   /* rtw88/rtw8822b_fw.bin in linux-firmware */
#define RTW_FW_MAX          (256u * 1024)

#define RTW_TX_DESC_SIZE    48
#define RTW_RX_DESC_SIZE    24
#define RTW_EFUSE_PHYSICAL  1024
#define RTW_EFUSE_LOGICAL   768
#define RTW_EFUSE_PROTECT   96
#define RTW_EFUSE_MAC       0x107               /* rtw8822bu_efuse.mac_addr */

/* rtw88's queue selectors and where they leave (rtw_usb_parse with the
 * 8822B's rqpn table for three bulk OUT endpoints: high, normal, low). */
#define RTW_QSEL_BE         0
#define RTW_QSEL_BEACON     16
#define RTW_QSEL_MGMT       18
#define RTW_QSEL_H2C        19
#define RTW_EP_HIGH         0                   /* beacon, H2C, management */
#define RTW_EP_NORMAL       1                   /* voice, video */
#define RTW_EP_LOW          2                   /* best effort, background */
#define RTW_OUT_MAX         4
#define RTW_TX_COUNT        32
#define RTW_TX_SLOT         12296       /* six descriptors and frames (RTW_TX_AGG), 8 to pad */
#define RTW_TX_AGG          6           /* frames to a transfer (usb_tx_agg_desc_num is 3) */
#define RTW_RX_COUNT        8
#define RTW_RX_SIZE         20480       /* rtw88 takes 32 KB; one EHCI qTD carries 20 */

/* Steps of the bring-up, kept in the stats when one fails. */
enum {
    RTW_STEP_OK = 0,
    RTW_STEP_DMA = 1,
    RTW_STEP_ENDPOINTS,
    RTW_STEP_CHIP,              /* reading the chip's version */
    RTW_STEP_FW_FILE,           /* finding or reading rtw8822b_fw.bin */
    RTW_STEP_POWER_ON,
    RTW_STEP_FW_DOWNLOAD,
    RTW_STEP_FW_READY,
    RTW_STEP_EFUSE,
    RTW_STEP_MAC_INIT,
    RTW_STEP_LLT,               /* the chip's own linked list of pages */
    RTW_STEP_H2C_QUEUE,
    RTW_STEP_RF_MODE,           /* the radio's mode table did not take */
    RTW_STEP_UP,                /* not a failure: powered, firmware running */
};

/* Read by tests/xectl.py; the field order is the struct's. */
typedef struct {
    u32 step;
    u32 step_status;
    u32 chip_version;           /* REG_SYS_CFG1 */
    u32 cut;                    /* its cut, 0 = A */
    u32 reg_reads;
    u32 reg_writes;
    u32 reg_errors;
    u32 reg_last_error;
    u32 reg_last_address;
    u32 fw_size;
    u32 fw_version;             /* version << 16 | subversion << 8 | subindex */
    u32 fw_h2c_version;
    u32 fw_ctrl;                /* REG_MCUFW_CTRL after the download */
    u32 poll_timeouts;
    u32 last_poll_address;
    u32 bulk_out;
    u32 bulk_errors;
    u32 bulk_last_error;
    u32 bulk_late;              /* bulk writes refused: the last one still out */
    u32 rfe_option;
    u32 crystal_cap;
    u32 mac_lo;                 /* the efuse's address, bytes 0-3 */
    u32 mac_hi;                 /* and 4-5 */
    u32 out_ep[RTW_OUT_MAX];
    u32 in_ep;
    u32 int_ep;
    u32 channel;
    u32 h2c_packets;
    u32 rx_transfers;
    u32 rx_frames;
    u32 rx_bad;
    u32 rx_c2h;
    u32 rx_crc_errors;
    u32 rx_errors;
    u32 rx_last_error;
    u32 rx_beacons;
    u32 rx_mgmt;
    u32 rx_data;
    s32 last_signal;
    u32 scans;
    u32 tx_frames;
    u32 tx_done;
    u32 tx_errors;
    u32 tx_last_error;
    u32 tx_drops;
    u32 tx_full;
    u32 keys;
    u32 linked;
    u32 h2c_commands;
    u32 h2c_busy;
    u32 ra_mask;
    u32 ra_rate_id;
    u32 ampdu;
    u32 rx_largest;             /* the longest receive transfer */
    u32 tx_inflight_now;
    u32 txpwr_ofdm6;            /* path A's power index at 6M, as last set */
    u32 txpwr_vht2_mcs7;        /* and at VHT 2SS MCS7 */
    u32 iqk_runs;
    u32 iqk_ms;                 /* how long the firmware's calibration took */
    u32 tx_stalls;              /* links dropped: transfers out, none completing */
    u32 rx_stalls;              /* card resets: no receive transfer for ~2 s */
    u32 stall_inflight;         /* at the last stall: slots taken, */
    u32 stall_ep_busy;          /* transfers out on the low endpoint, */
    u32 stall_open;             /* frames in its open transfer */
    u32 tx_transfers;           /* bulk transfers that carried tx_frames */
    u32 tx_aggregated;          /* transfers of more than one frame */
} RTW_STATS;

extern volatile RTW_STATS rtw_stats[USB_MAX_DEVICES];

typedef struct RTW {
    u32 in_use;
    NET_DEV *nd;
    USB_DEV *dev;
    volatile RTW_STATS *st;
    u32 cut;

    u8 *reg_buf;                /* DMA: one register's bytes, and 0x4e0's */
    u8 *bulk_buf;               /* DMA: one bulk transfer out, a firmware page */
    u8 *efuse;                  /* the logical map, RTW_EFUSE_LOGICAL bytes */
    u8 *fw;                     /* the firmware image, kept for a later bring-up */
    u32 fw_size;
    u32 rsvd_boundary;          /* the reserved pages' first, once the queues are set */
    u32 rsvd_h2cq_addr;         /* the firmware's command queue's first page */
    u32 channel;                /* tuned to, 0 before the first */
    u32 igi;                    /* the gain the tables left, for the DIG */

    void *ep_out[RTW_OUT_MAX];  /* high, normal, low priority (rtw_usb_parse) */
    u32 out_count;
    void *ep_in;
    void *ep_int;

    URB tx_urb;
    volatile u32 tx_done;
    volatile u32 tx_status;
    u32 h2c_seq;
    u32 h2c_box;                /* the next mailbox, 0-3 */

    u8 *rx_buf[RTW_RX_COUNT];
    URB rx_urb[RTW_RX_COUNT];
    volatile u32 rx_running;
    u32 rx_failing[RTW_RX_COUNT];       /* errors in a row on each transfer */
    volatile u32 rx_parked;             /* transfers left unqueued after too many */
    u32 rx_seen;                        /* the watchdog's last rx_transfers */
    u32 rx_quiet;

    u32 scan_index;             /* the channel being listened on, while scanning */
    u32 scan_ticks;
    u32 scan_wait;              /* worker ticks until the next scan */

    u8 *tx_buf[RTW_TX_COUNT];
    URB tx_slot_urb[RTW_TX_COUNT];
    volatile u32 tx_busy[RTW_TX_COUNT];
    volatile u32 tx_next;
    volatile u32 tx_inflight;           /* slots taken: in a transfer or being filled */
    volatile u32 tx_ready;
    u32 tx_seen;                        /* the watchdog's last tx_done */
    u32 tx_quiet;                       /* its ticks without one */
    KSPIN_LOCK tx_lock;                 /* the open aggregates and the counts by endpoint */
    u32 tx_slot_ep[RTW_TX_COUNT];
    u32 tx_ep_busy[RTW_OUT_MAX];        /* transfers out on each endpoint */
    u32 tx_open[RTW_OUT_MAX];           /* the slot frames are joining, or RTW_TX_COUNT */
    u32 tx_open_length[RTW_OUT_MAX];
    u32 tx_open_frames[RTW_OUT_MAX];
    u32 port_macid;             /* the station port's own, 0 */
    u32 data_rate;              /* DESC_RATE* data goes at, until the firmware picks */
    u32 data_rate_id;
    u32 data_bw;
    u32 data_sgi;
    u32 data_use_rate;          /* the rate in the descriptor, not the firmware's */
    u32 data_ldpc;
    u32 data_stbc;
    volatile u32 ampdu;         /* aggregate data (a block-ack session to the AP) */
    u32 ampdu_factor;           /* the descriptor's MAX_AGG_NUM */
    u32 ampdu_density;

    WL_SOFTMAC ops;             /* this card, for the station */
    WL_STA sta;
    WL_LINK link;               /* the Wi-Fi mode, and its state for this card */
} RTW;

/* --- registers (rtw_usb.c) -------------------------------------------------------- */

u8   rtw_read8(RTW *r, u32 address);
u16  rtw_read16(RTW *r, u32 address);
u32  rtw_read32(RTW *r, u32 address);
void rtw_write8(RTW *r, u32 address, u8 value);
void rtw_write16(RTW *r, u32 address, u16 value);
void rtw_write32(RTW *r, u32 address, u32 value);

/* rtw88's helpers over those, same names. */
void rtw_write8_set(RTW *r, u32 address, u8 bits);
void rtw_write8_clr(RTW *r, u32 address, u8 bits);
void rtw_write16_set(RTW *r, u32 address, u16 bits);
void rtw_write16_clr(RTW *r, u32 address, u16 bits);
void rtw_write32_set(RTW *r, u32 address, u32 bits);
void rtw_write32_clr(RTW *r, u32 address, u32 bits);
void rtw_write32_mask(RTW *r, u32 address, u32 mask, u32 value);
void rtw_write8_mask(RTW *r, u32 address, u32 mask, u8 value);
u32  rtw_read32_mask(RTW *r, u32 address, u32 mask);

/* Poll `address` until (value & mask) is `target`, 1000 times 10 us apart as
 * check_hw_ready: 1 if it came. */
u32  rtw_check_hw_ready(RTW *r, u32 address, u32 mask, u32 target);

/* One bulk transfer out on endpoint `ep` (RTW_EP_*), waited for. Thread-only. */
u32  rtw_bulk_out(RTW *r, u32 ep, const u8 *data, u32 length);

/* The bulk endpoints, by the interface's descriptors (rtw_usb_parse). */
u32  rtw_usb_open(RTW *r);

/* --- the MAC: power and firmware (rtw_mac.c) --------------------------------------- */

u32  rtw_mac_power_on(RTW *r);
void rtw_mac_power_off(RTW *r);
u32  rtw_download_firmware(RTW *r);

/* rtw_mac_init with the 8822B's mac_init and the USB interface's: the queues,
 * the reserved pages, the H2C queue, protocol timing and the receive filters.
 * 0, or the step that failed. */
u32  rtw_mac_init(RTW *r);

/* --- baseband and radio (rtw_phy.c) ---------------------------------------------- */

u32  rtw_read_rf(RTW *r, u32 path, u32 addr, u32 mask);
void rtw_write_rf(RTW *r, u32 path, u32 addr, u32 mask, u32 data);

/* rtw8822b_phy_set_param: BB and RF powered, their tables loaded, both paths.
 * 0, or the step that failed. */
u32  rtw_phy_set_param(RTW *r);

/* rtw8822b_set_channel: `bw` 0 20 MHz, 1 40, 2 80; `primary` RTW_SC_* of the
 * 20 MHz channel in it, 0 at 20 MHz. */
void rtw_set_channel(RTW *r, u32 channel, u32 bw, u32 primary);
void rtw_iqk(RTW *r);

/* --- firmware commands (rtw_fw.c) -------------------------------------------------- */

u32  rtw_fw_send_general_info(RTW *r);
u32  rtw_fw_send_phydm_info(RTW *r);
u32  rtw_fw_media_status(RTW *r, u32 macid, u32 connected);
u32  rtw_fw_iqk(RTW *r);
u32  rtw_fw_ra_info(RTW *r, u32 macid, u32 rate_id, u32 init_level, u32 sgi, u32 bw,
                    u32 ldpc, u32 vht, u32 mask);

/* --- transmit and keys (rtw_tx.c) ------------------------------------------------- */

/* softmac.h's WL_TX_* */
#define RTW_TX_MGMT     0x01u
#define RTW_TX_PROTECT  0x02u
#define RTW_TX_EAPOL    0x04u
#define RTW_TX_GROUP    0x08u

u32  rtw_tx(RTW *r, const u8 *head, u32 head_length, const u8 *body, u32 body_length,
            u32 flags, u32 tid);
u32  rtw_tx_space(RTW *r);
u32  rtw_set_key(RTW *r, u32 pairwise, u32 index, const u8 *key, u32 length, const u8 *peer);
void rtw_clear_keys(RTW *r);

/* --- receive (rtw_rx.c) ------------------------------------------------------------ */

/* Queue every receive buffer. Thread. */
void rtw_rx_start(RTW *r);

/* One received 802.11 frame without its FCS, in the receive buffer (it may be
 * written over), the signal in dBm and the descriptor's first word; rtw8822b.c's.
 * DISPATCH_LEVEL. */
void rtw_rx_frame(RTW *r, u8 *frame, u32 length, s32 signal, u32 desc_w0);

/* --- the efuse (rtw_efuse.c) ------------------------------------------------------- */

u32  rtw_parse_efuse_map(RTW *r);

#endif /* XE_RTW_H */
